<?php
require '../includes/header.php';require '../includes/role_guard.php';requireRole(['admin','staff','tribe_leader','tribe_rep','assessor']);require '../includes/db.php';require_once '../includes/tax_access.php';
$q=trim((string)($_GET['q']??''));$type=(int)($_GET['property_type']??0);$taxStatus=(string)($_GET['tax_status']??'');$recordStatus=(string)($_GET['declaration_status']??'');$parcelId=(int)($_GET['parcel_id']??0);$scope=tax_scope($conn);$where=['1=1'];
if($scope!==null)$where[]="t.owning_tribe='".$conn->real_escape_string($scope)."'";if($parcelId)$where[]="t.parcel_id=$parcelId";if($q!==''){$s=$conn->real_escape_string($q);$where[]="(t.td_number LIKE '%$s%' OR t.pin LIKE '%$s%' OR t.owner_name LIKE '%$s%' OR t.location_barangay LIKE '%$s%' OR t.lot_number LIKE '%$s%' OR EXISTS(SELECT 1 FROM tax_declaration_assessments a WHERE a.tax_declaration_id=t.id AND (a.classification LIKE '%$s%' OR a.actual_use LIKE '%$s%')))";}if($type)$where[]="t.property_type_id=$type";if(in_array($taxStatus,['taxable','exempt'],true))$where[]="t.tax_status='$taxStatus'";if(in_array($recordStatus,['current','historical','cancelled'],true))$where[]="t.declaration_status='$recordStatus'";
$w=implode(' AND ',$where);$total=(int)$conn->query("SELECT COUNT(*) FROM tax_declarations t WHERE $w")->fetch_row()[0];[$page,$perPage,$offset,$pages]=pagination_values($total);$rows=$conn->query("SELECT t.id,t.td_number,t.pin,t.owner_name,t.location_barangay,t.tax_status,t.declaration_status,pt.name property_type,p.land_name parcel_name FROM tax_declarations t LEFT JOIN property_types pt ON pt.id=t.property_type_id LEFT JOIN ip_land_parcels p ON p.id=t.parcel_id WHERE $w ORDER BY t.id DESC LIMIT $perPage OFFSET $offset")->fetch_all(MYSQLI_ASSOC);$types=$conn->query("SELECT id,name FROM property_types WHERE status='active' ORDER BY name")->fetch_all(MYSQLI_ASSOC);
?><main class="main-no-right"><div class="page-heading"><div><h4>Tax Declarations</h4><p>Property assessment records linked to existing parcels only when verified.</p></div><a class="btn btn-success" href="tax_declarations/create.php"><i class="bi bi-plus-lg"></i> New Declaration</a></div>
<form class="card-box mb-3"><div class="row g-2"><div class="col-md-4"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="TD number, PIN, owner, lot, classification..."></div><div class="col-md-2"><select class="form-select" name="property_type"><option value="">All property types</option><?php foreach($types as$x):?><option value="<?=$x['id']?>" <?=$type==(int)$x['id']?'selected':''?>><?=e($x['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><select class="form-select" name="tax_status"><option value="">All tax status</option><option value="taxable" <?=$taxStatus==='taxable'?'selected':''?>>Taxable</option><option value="exempt" <?=$taxStatus==='exempt'?'selected':''?>>Exempt</option></select></div><div class="col-md-2"><select class="form-select" name="declaration_status"><option value="">Current and history</option><?php foreach(['current','historical','cancelled']as$s):?><option value="<?=$s?>" <?=$recordStatus===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-success w-100">Filter</button></div></div></form>
<div class="card-box p-0"><table class="table table-hover"><thead><tr><th>TD / PIN</th><th>Owner</th><th>Property</th><th>Location</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6"><div class="empty-state border-0"><h5>No Tax Declarations found</h5></div></td></tr><?php endif;?><?php foreach($rows as$r):?><tr><td data-label="TD / PIN"><strong><?=e($r['td_number'])?></strong><small class="d-block text-muted"><?=e($r['pin']?:'No PIN')?></small></td><td data-label="Owner"><?=e($r['owner_name'])?></td><td data-label="Property"><?=e($r['property_type']?:'Not recorded')?><?php if($r['parcel_name']):?><small class="d-block text-muted"><?=e($r['parcel_name'])?></small><?php endif;?></td><td data-label="Location"><?=e($r['location_barangay']?:'—')?></td><td data-label="Status"><span class="badge bg-secondary"><?=e($r['tax_status']?:'unclassified')?></span> <small><?=e($r['declaration_status'])?></small></td><td class="text-end"><a class="btn btn-sm btn-light border" href="tax_declarations/view.php?id=<?=$r['id']?>">View</a></td></tr><?php endforeach;?></tbody></table></div><?php render_pagination($page,$pages);?></main><?php require '../includes/footer.php';?>
